    "geez_script": `አቡነ ዘበሰማያት፣ ይትቀደስ ስምከ። ትምጻእ መንግሥትከ ወይኩን ፈቃድከ በከመ በሰማይ ከማሁ በምድር።`,
    "geez_phonetic": `abune zebesemayat, ytḳedes smke. tmtsa'i mengstke weykun feḳadke bekeme besemay kemahu bemdr.`,
