    "reference": `Monday Praise of Mary`,
    "chapter": `Mon`,
    "stanza": `2`,
    "english": `፨ Reader: He shone in the flesh from the Virgin without the seed of man, and He saved us.`,
    "geez_script": `፨ አንባቢ፤ ሠረቀ በሥጋ እምድንግል ዘእንበለ ዘርአ ብእሲ ወአድኀነነ።`,
