    "english": `But His heart delighted in the love for mankind and He set her free. O holy one (Mary), pray for us.`,
    "geez_script": `ሠምረ ልቡ ኀበ ፍቅረ ሰብእ ወአግዓዛ። ሰአሊ ለነ ቅድስት።`,
