    "geez_phonetic": `፨ 'anbabī: ḥzḳ'él nebīy kone sm'a be'intī'aha weybé r'īku hohte bemsraḳ htum be'abīy menkr mahtem 'albo zebo'a ze'inbele 'igzī'a hayalan bo'a wstéta wewets'a. se'alī lene ḳdst.`,
