    "english": ``,
    "geez_script": `፨ አንባቢ፤ ኖኅትስ ድንግል ይእቲ እንተ ወለደት ለነ መድኅነ፣ እምድኅረ ወለደት ኪያሁ ነበረት በድንግልና ከመ ትካት።`,
