    "stanza": `8`,
    "english": ``,
    "geez_script": `አንቲ ፍጽምት ወቡርክት፣ ረከብኪ ሞገሰ በኀበ ንጉሠ ስብሐት አምላክ ዘበአማን ለኪ ይደሉ ዕበይ ወክብር እምኵሎሙ እለ ይነብሩ ዲበ ምድር፡ ቃለ አብ መጽአ ወተሰብአ እምኔኪ።`,
