    "geez_script": `፨ አንባቢ፤ በትረ አሮን እንተ ሠረፀት ዘእንበለ ተክል ወኢሠቀይዋ ማየ፡ ከማሃ አንቲኒ ኦ ወላዲተ ክርስቶስ አምላክነ ዘበአማን ዘእንበለ ዘርዕ መጽአ ወአድኀነነ። ሰአሊ ለነ ቅድስት።`,
    "geez_phonetic": `፨ 'anbabī: betre 'aron 'inte seretset ze'inbele tekl we'īseḳeywa maye kemaha 'antīnī 'o weladīte krstos 'amlakne zebe'aman ze'inbele zer'i mets'a we'adhanene. se'alī lene ḳdst.`,
    "amharic_script": ``,
