    "amharic_phonetic": `ineho; ttsenshalesh: wend ljnm tweljalesh: smunm 'īyesus tywalesh.`,
    "tigrinya_script": `እንሆ ኽትጠንሲ፥ ወዲውን ክትወልዲ ኢኺ፤ ስሙ ድማ ኢየሱስ ክትብልዮ ኢኺ።`,
