    "tigrinya_script": `እቲ መልኣኽ መሊሱ ኸምዙይ በለ፦ “መንፈስ ቅዱስ ናባኺ ኽመፅእ እዩ፤ ሓይሊ ልዑል እግዚኣብሄርውን ከፅልለልኪ እዩ፤`,
